/**
 * # Active site (compatibility setters)
 *
 * Two setters, called at module load from each site's `site.config.ts`,
 * that build and install a `SiteContext` (see `site-context.ts`). Code
 * that calls them gets the same guarantees as code that installs a
 * context directly — one validated site key, one origin, and one clock
 * captured when the key is first set — and the same failure: with no
 * key set, resolving featured state throws `MissingSiteContextError`.
 *
 * Prefer `createSiteContext` + `setActiveSiteContext`, and prefer
 * passing that context to builders over relying on it being installed.
 * These setters remain because all three sites call them; moving a
 * site off them is a mechanical change that does not alter behaviour.
 */
import { createSiteContext, getActiveSiteContext, normalizeOrigin, setActiveSiteContext, } from "./site-context.js";
// The two setters are independent calls, in either order, so an origin
// set before the key has to be held until there is a context to put it in.
let pendingOrigin;
/**
 * Install a site context for `key`, keeping any origin already set and
 * the clock of any context already installed. Passing `undefined`
 * uninstalls the context.
 *
 * @deprecated Use `setActiveSiteContext(createSiteContext({ ... }))`.
 */
export function setActiveSiteKey(key) {
    if (!key) {
        setActiveSiteContext(undefined);
        return;
    }
    const current = getActiveSiteContext();
    setActiveSiteContext(createSiteContext({
        siteKey: key,
        origin: current?.origin ?? pendingOrigin,
        basePath: current?.basePath,
        now: current?.now,
    }));
}
/**
 * The installed context's site key, or `undefined` when none is
 * installed. Callers must treat `undefined` as "unknown", never as "any
 * site".
 *
 * @deprecated Read `siteKey` from a `SiteContext`.
 */
export function getActiveSiteKey() {
    return getActiveSiteContext()?.siteKey;
}
/**
 * Record the origin this build deploys to (e.g. `https://vizij.ai`),
 * from `astro.config`'s `site`. An unparseable value is recorded as
 * unknown rather than thrown, matching how self-link detection treats
 * an absent origin.
 *
 * It exists so shared code can tell "a link to this very page" from "a
 * link to the same path on a sibling site." The three sites share one
 * content hub and use the same route shapes, so
 * `https://semio.community/events/x` and `https://vizij.ai/events/x`
 * differ only by origin — and on vizij only the second is a self-link.
 *
 * @deprecated Pass `origin` to `createSiteContext`.
 */
export function setActiveSiteOrigin(origin) {
    pendingOrigin = normalizeOrigin(origin);
    const current = getActiveSiteContext();
    if (current) {
        setActiveSiteContext(createSiteContext({
            siteKey: current.siteKey,
            origin: pendingOrigin,
            basePath: current.basePath,
            now: current.now,
        }));
    }
}
/**
 * This build's origin in bare `https://host` form, or `undefined` when
 * unknown — which callers must treat as "cannot tell", never as "not
 * this site."
 *
 * @deprecated Read `origin` from a `SiteContext`.
 */
export function getActiveSiteOrigin() {
    const current = getActiveSiteContext();
    return current ? current.origin : pendingOrigin;
}
